LAYER
  NAME "t_rezago_educativo_analfabeta_loc_urb_manzana"
  STATUS ON
  TYPE LINE
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, analfabeta FROM rezago_educativo_censo_2020.rez_loc_urb_manzanas_limpio WHERE the_geom && !BOX!) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Texto Rezago de analfabetismo por localidad urbana (manzana)"
    "wms_enable_request" "*"
  END
